@Configuration
@EnableWebSecurity
@EnableMethodSecurity
public class SecurityConfig {

    private final JwtAuthenticationFilter jwtFilter;

    public SecurityConfig(JwtAuthenticationFilter jwtFilter) {
        this.jwtFilter = jwtFilter;
    }

    @Bean
    SecurityFilterChain apiChain(HttpSecurity http) throws Exception {
        http
            .csrf(AbstractHttpConfigurer::disable)
            .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/v1/auth/**").permitAll()
                .requestMatchers(HttpMethod.GET, "/api/v1/topics/**").permitAll()
                .requestMatchers("/api/v1/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated())
            .exceptionHandling(ex -> ex
                .authenticationEntryPoint(restEntryPoint())
                .accessDeniedHandler(restDeniedHandler()))
            .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    @Bean
    AuthenticationEntryPoint restEntryPoint() {
        return (request, response, ex) ->
                response.sendError(HttpServletResponse.SC_UNAUTHORIZED);
    }

    @Bean
    AccessDeniedHandler restDeniedHandler() {
        return (request, response, ex) ->
                response.sendError(HttpServletResponse.SC_FORBIDDEN);
    }
}

@Service
public class TopicAdminService {

    private final TopicRepository topics;

    public TopicAdminService(TopicRepository topics) {
        this.topics = topics;
    }

    @PreAuthorize("hasRole('ADMIN')")
    public void delete(Long id) {
        topics.deleteById(id);
    }

    @PreAuthorize("hasRole('ADMIN') or #authorId == authentication.principal.id")
    public Topic update(Long id, Long authorId, TopicForm form) {
        Topic topic = topics.findById(id).orElseThrow(NotFoundException::new);
        topic.apply(form);
        return topics.save(topic);
    }
}
